import queue

import pytest


def accepted(cap: int, xs: list[int]) -> int:
    """Count puts accepted by a bounded queue before it is full.

    Creates a queue.Queue holding at most `cap` integers and tries to put
    each element of `xs` in order without blocking (put_nowait). Stops at
    the first put rejected because the queue is full and returns the number
    of puts accepted up to that point. Nothing is ever taken out of the
    queue. A capacity of zero or less means no room, so the result is 0.
    """
    if cap <= 0:
        return 0
    q: queue.Queue[int] = queue.Queue(maxsize=cap)
    count = 0
    for x in xs:
        try:
            q.put_nowait(x)
        except queue.Full:
            break
        count += 1
    return count


def test_stops_when_full() -> None:
    assert accepted(2, [10, 20, 30, 40]) == 2


def test_cap_larger_than_input() -> None:
    assert accepted(10, [1, 2, 3]) == 3


def test_exact_fit() -> None:
    assert accepted(3, [1, 2, 3]) == 3


def test_empty_input() -> None:
    assert accepted(5, []) == 0


def test_zero_capacity() -> None:
    assert accepted(0, [1, 2, 3]) == 0


def test_negative_capacity() -> None:
    assert accepted(-1, [1, 2]) == 0


def test_duplicates_are_counted() -> None:
    assert accepted(3, [7, 7, 7, 7, 7]) == 3


@pytest.mark.parametrize(
    ("cap", "n", "expected"),
    [(1, 5, 1), (4, 4, 4), (4, 3, 3), (0, 0, 0)],
)
def test_parametrized(cap: int, n: int, expected: int) -> None:
    assert accepted(cap, list(range(n))) == expected
